class Solution {
public:
    int numberOfWays(int n, int m, int k, vector<int>& source, vector<int>& dest) {
        const long long MOD = 1e9 + 7;
        long long A = 0, B = 0, C = 0, D = 0;
        if (source == dest) A = 1;
        else if (source[0] == dest[0]) B = 1;
        else if (source[1] == dest[1]) C = 1;
        else D = 1;
        while (k--) {
            long long na = (B + C) % MOD;
            long long nb = ((n - 1) * A + (n - 2) * B + D) % MOD;
            long long nc = ((m - 1) * A + (m - 2) * C + D) % MOD;
            long long nd = ((m - 1) * B + (n - 1) * C + (n + m - 4) * D) % MOD;
            A = na; B = nb; C = nc; D = nd;
        }
        return A;
    }
};

